<template>
  <div class="pm-table-scroll">
    <table class="pm-material-table">
      <thead><tr><th class="pm-index">序号</th><th>物料信息</th><template v-if="mode === 'plan'"><th>需求数量</th><th>已配数量</th><th>待配数量</th><th>库存来源</th></template><template v-else-if="mode === 'assign' || mode === 'pick'"><th>库存来源</th><th v-if="mode === 'pick'">计划数量</th></template><template v-else-if="mode === 'send'"><th>{{ redelivery ? '拒收数量' : '已拣' }}</th><th>{{ redelivery ? '已补送' : '已分配' }}</th><th>{{ redelivery ? '可补送' : '可配送' }}</th></template><template v-else-if="mode === 'receipt'"><th>配送数量</th><th>实收数量</th><th>拒收数量</th></template><th>{{ lastLabel }}</th><th class="pm-expand" /></tr></thead>
      <tbody>
        <template v-for="(group, index) in groups">
          <tr :key="group.key"><td>{{ index + 1 }}</td><td class="pm-material-name"><strong>{{ group.name }}</strong><small>{{ group.code }}<template v-if="group.spec"> · {{ group.spec }}</template></small><small v-if="cuttingTotalLength(group.demand)">待覆盖总用量 {{ totalLengthMetres(group.demand.remaining_cut_total_length_mm) || '—' }} m</small><small v-if="group.demand && group.demand.cutting_member_requirements">已合并 {{ group.demand.cutting_member_requirements.length }} 条下料明细</small><el-button v-if="mode === 'plan' && cuttingWholeStock(group.demand) && !cuttingTotalLength(group.demand)" type="text" @click="$emit('combine',group)">合并下料明细</el-button></td>
            <template v-if="mode === 'plan'"><td>{{ qty(group.required) }} {{ group.unit }}</td><td>{{ qty(group.allocated) }} {{ group.unit }}</td><td class="pm-warning">{{ qty(group.remaining) }} {{ group.unit }}</td><td><span v-if="group.sources.length > 1">已选 {{ group.sources.length }} 个库存来源</span><span v-else-if="group.sources.length">{{ location(group.sources[0]) }}<small>批次 {{ group.sources[0].batch_no }}</small></span><span v-else>未选择库存</span><el-button type="text" @click="$emit('stock', group)">选择库存</el-button></td></template>
            <template v-else-if="mode === 'assign' || mode === 'pick'"><td>{{ group.sources.length > 1 ? '已选 ' + group.sources.length + ' 个库存来源' : location(group.sources[0]) }}<small v-if="group.sources.length === 1">{{ group.sources[0].batch_no }}</small></td><td v-if="mode === 'pick'">{{ sum(group, 'planned') }} {{ group.unit }}</td></template>
            <template v-else-if="mode === 'send'"><td>{{ sum(group, 'picked') }} {{ group.unit }}</td><td>{{ sum(group, 'allocated') }} {{ group.unit }}</td><td>{{ sum(group, 'available') }} {{ group.unit }}</td></template>
            <template v-else><td>{{ sum(group, 'delivered') }} {{ group.unit }}</td><td>{{ sum(group, 'received') }} {{ group.unit }}</td><td :class="{ 'pm-warning': Number(sum(group, 'rejected')) > 0 }">{{ sum(group, 'rejected') }} {{ group.unit }}</td></template>
            <td class="pm-quantity"><span v-if="mode === 'receipt'">{{ sum(group, 'pending') }} {{ group.unit }}</span><span v-else-if="mode === 'assign'">{{ sum(group, 'planned') }} {{ group.unit }}</span><el-input v-else-if="editable && group.sources.length === 1 && !sheetPlan(group.sources[0])" v-model="group.sources[0].quantity" size="small" inputmode="decimal" :class="{ 'pm-invalid': invalid(group.sources[0]) }"><span slot="append">{{ group.unit }}</span></el-input><strong v-else>{{ sum(group, 'quantity') }} {{ group.unit }}</strong><div v-if="mode === 'plan' && group.sources.length === 1 && cuttingWholeStock(group.sources[0]) && !group.sources[0].cutting_members" class="pm-cut-pieces"><small>{{ cuttingTotalLength(group.sources[0]) ? '本次覆盖总用量' : '本次加工件数' }}</small><el-input v-if="cuttingTotalLength(group.sources[0])" v-model="group.sources[0].planned_cut_total_length_m" size="small" inputmode="decimal" @input="setTotalLength(group.sources[0], $event)"><span slot="append">m</span></el-input><el-input v-else v-model="group.sources[0].planned_cut_piece_qty" size="small" inputmode="numeric"><span slot="append">{{ group.sources[0].cutting_unit_kind === 'root' ? '段' : '块' }}</span></el-input></div></td>
            <td><el-button v-if="group.sources.length" type="text" :icon="group.expanded ? 'el-icon-arrow-up' : 'el-icon-arrow-down'" :aria-label="(group.expanded ? '收起' : '展开') + group.name" @click="$set(group, 'expanded', !group.expanded)" /></td>
          </tr>
          <tr v-if="group.expanded && group.sources.length" :key="group.key + '-sources'"><td /><td :colspan="columns - 1" class="pm-sources-cell"><table class="pm-source-table"><thead><tr><th>库位</th><th>批次</th><th v-if="mode === 'plan'">可用数量</th><th v-else-if="mode === 'pick'">计划数量</th><template v-else-if="mode === 'send'"><th>{{ redelivery ? '拒收数量' : '已拣' }}</th><th>{{ redelivery ? '已补送' : '已分配' }}</th><th>{{ redelivery ? '可补送' : '可配送' }}</th></template><template v-else-if="mode === 'receipt'"><th>配送数量</th><th>{{ editable ? '本次实收' : '实收数量' }}</th><th>{{ editable ? '本次拒收' : '拒收数量' }}</th></template><th>{{ lastLabel }}</th><th v-if="mode === 'plan'">操作</th><th v-if="mode === 'receipt'">拒收原因</th></tr></thead><tbody>
            <tr v-for="source in group.sources" :key="source.id"><td>{{ location(source) }}</td><td>{{ source.batch_no }}</td><td v-if="mode === 'plan'">{{ qty(source.picking_available_qty) }} {{ group.unit }}</td><td v-else-if="mode === 'pick'">{{ qty(source.planned) }} {{ group.unit }}</td><template v-else-if="mode === 'send'"><td>{{ qty(source.picked) }} {{ group.unit }}</td><td>{{ qty(source.allocated) }} {{ group.unit }}</td><td>{{ qty(source.available) }} {{ group.unit }}</td></template><template v-else-if="mode === 'receipt'"><td>{{ qty(source.delivered) }} {{ group.unit }}</td><td><template v-if="editable"><el-input v-model="source.receiptAccepted" size="small" inputmode="decimal" :readonly="source.serialRequired" :disabled="receiptLocked || source.pending <= 0" :aria-label="group.name + '本次实收数量'" :class="{ 'pm-invalid': receiptInvalid(source) }"><span slot="append">{{ group.unit }}</span></el-input><el-button v-if="source.serialRequired" type="text" :disabled="receiptLocked || source.pending <= 0" @click="$emit('receipt-serials', { source, disposition: 'accepted' })">选择实收序列号（{{ source.receiptAcceptedSerials.length }}）</el-button><small>已实收 {{ qty(source.received) }} {{ group.unit }}</small></template><span v-else>{{ qty(source.received) }} {{ group.unit }}</span></td><td><template v-if="editable"><el-input v-model="source.receiptRejected" size="small" inputmode="decimal" :readonly="source.serialRequired" :disabled="receiptLocked || source.pending <= 0" :aria-label="group.name + '本次拒收数量'" :class="{ 'pm-invalid': receiptInvalid(source) }"><span slot="append">{{ group.unit }}</span></el-input><el-button v-if="source.serialRequired" type="text" :disabled="receiptLocked || source.pending <= 0" @click="$emit('receipt-serials', { source, disposition: 'rejected' })">选择拒收序列号（{{ source.receiptRejectedSerials.length }}）</el-button><small>已拒收 {{ qty(source.rejected) }} {{ group.unit }}</small><small v-if="receiptInvalid(source)" class="pm-danger">请核对数量，实收与拒收合计不能超过待确认数量。</small></template><span v-else>{{ qty(source.rejected) }} {{ group.unit }}</span></td></template>
              <td class="pm-quantity"><span v-if="mode === 'receipt'">{{ qty(source.pending) }} {{ group.unit }}</span><span v-else-if="mode === 'assign'">{{ qty(source.planned) }} {{ group.unit }}</span><template v-else-if="editable"><span v-if="sheetPlan(source)">{{ qty(source.quantity) }} {{ group.unit }} <el-button type="text" @click="$emit('stock', group)">调整选板方案</el-button></span><el-input v-else v-model="source.quantity" size="small" inputmode="decimal" :class="{ 'pm-invalid': invalid(source) }"><span slot="append">{{ group.unit }}</span></el-input><div v-if="mode === 'plan' && cuttingWholeStock(source) && !source.cutting_members" class="pm-cut-pieces"><small>{{ cuttingTotalLength(source) ? '本次覆盖总用量' : '本次加工件数' }}</small><el-input v-if="cuttingTotalLength(source)" v-model="source.planned_cut_total_length_m" size="small" inputmode="decimal" @input="setTotalLength(source, $event)"><span slot="append">m</span></el-input><el-input v-else v-model="source.planned_cut_piece_qty" size="small" inputmode="numeric"><span slot="append">{{ source.cutting_unit_kind === 'root' ? '段' : '块' }}</span></el-input></div><small v-if="invalid(source)" class="pm-danger">{{ cuttingTotalLength(source) ? '请核对实际原料数量及覆盖总用量' : '请核对原料数量及加工件数' }}</small><el-button v-if="source.serialRequired && mode !== 'plan'" type="text" @click="$emit('serials', source)">选择序列号（{{ (source.serials || []).length }}）</el-button><el-button v-if="source.physicalRequired && mode === 'pick'" type="text" @click="$emit('physicals', source)">选择本次原料（{{ (source.physicals || []).length }} 张）</el-button></template><span v-else>{{ qty(source.quantity) }} {{ group.unit }}</span><small v-for="member in source.cutting_members || []" :key="member.target_material_requirement_id">{{ memberDimensions(source, member) }}：{{ member.planned_cut_piece_qty }} 件</small><small v-if="source.cuttingAllocation && cuttingTotalLength(source.cuttingAllocation)">按总用量<template v-if="plannedTotalLength(source.cuttingAllocation)"> · 计划覆盖 {{ plannedTotalLength(source.cuttingAllocation) }} m</template></small><small v-else-if="source.cuttingAllocation">计划加工 {{ source.cuttingAllocation.planned_cut_piece_qty }} {{ source.cuttingAllocation.unit_kind === 'root' ? '段' : '块' }}</small><details v-if="boardPlan(source).length" class="pm-board-plan-summary"><summary>查看逐板下料方案（{{ boardPlan(source).length }} 张）</summary><div v-for="board in boardPlan(source)" :key="board.physical_material_id"><strong>{{ board.physical_no || ('板材 ' + board.physical_material_id) }}</strong><small v-for="member in board.members || []" :key="member.target_material_requirement_id">{{ memberDimensions(source, member) }}：{{ member.planned_cut_piece_qty == null ? member.covered_piece_qty : member.planned_cut_piece_qty }} 件</small></div></details></td>
              <td v-if="mode === 'plan'"><el-button type="text" @click="group.sources.splice(group.sources.indexOf(source), 1)">移除</el-button></td><td v-if="mode === 'receipt'"><template v-if="editable"><template v-if="source.serialRequired"><div v-for="serial in source.receiptRejectedSerials" :key="serial.id"><small>{{ serial.serial_no }}</small><el-input v-model="serial.reason" size="small" maxlength="500" :disabled="receiptLocked" :aria-label="serial.serial_no + '拒收原因'" placeholder="请填写该序列号的拒收原因" /></div><small v-if="source.receiptRejectedSerials.some(row => !String(row.reason || '').trim())" class="pm-danger">每个拒收序列号均须填写原因。</small></template><template v-else><el-input v-model="source.receiptReason" size="small" maxlength="500" :disabled="receiptLocked || source.pending <= 0" :aria-label="group.name + '拒收原因'" :placeholder="Number(source.receiptRejected) > 0 ? '拒收原因（必填）' : '无拒收时可留空'" /><small v-if="Number(source.receiptRejected) > 0 && !String(source.receiptReason || '').trim()" class="pm-danger">请填写拒收原因。</small></template><small v-if="source.rejectReason">已登记：{{ source.rejectReason }}</small></template><span v-else>{{ source.rejectReason || '—' }}</span></td>
            </tr></tbody></table><div v-if="mode === 'plan'" class="pm-source-summary"><el-button type="text" icon="el-icon-plus" @click="$emit('stock', group)">添加库存来源</el-button><strong>合计：{{ sum(group, 'quantity') }} {{ group.unit }}</strong></div></td></tr>
        </template>
        <tr v-if="!groups.length"><td :colspan="columns" class="pm-empty">暂无物料明细</td></tr>
      </tbody>
    </table>
  </div>
</template>
<script>
import { cuttingWholeStock, cuttingTotalLength, validCuttingSource, cuttingDimensions } from '@/utils/production-cutting-allocation.mjs'
import { totalLengthMetres, totalLengthMillimetres } from '@/utils/cutting-quantity.mjs'
export default {
  props: { groups: { type: Array, default: () => [] }, mode: { type: String, default: 'plan' }, editable: Boolean, redelivery: Boolean, receiptLocked: Boolean },
  computed: { columns() { return this.mode === 'plan' ? 8 : this.mode === 'assign' ? 5 : this.mode === 'pick' ? 6 : 7 }, lastLabel() { return ({ plan: '本次配料', pick: '实拣数量', assign: '计划配料', send: this.redelivery ? '本次补送' : '本次配送', receipt: '待确认' })[this.mode] } },
  methods: {
    cuttingWholeStock, cuttingTotalLength, totalLengthMetres,
    sheetPlan(source) { return source.cutting_unit_kind === 'sheet' && !!source.cutting_source_plan },
    boardPlan(source) { return source.cutting_source_plan?.sources || (source.cuttingAllocation?.unit_kind === 'sheet' ? source.cuttingAllocation.sources : []) || [] },
    setTotalLength(row, value) { this.$set(row, 'planned_cut_total_length_mm', totalLengthMillimetres(value, 5)) },
    plannedTotalLength(allocation) { const member=allocation.members?.find(row=>Number(row.target_material_requirement_id)===Number(allocation.target_material_requirement_id)); return totalLengthMetres(member?.covered_total_length_mm) },
    memberDimensions(source, member) { const row=(source.cutting_member_requirements || []).find(row=>Number(row.id ?? row.target_material_requirement_id)===Number(member.target_material_requirement_id)); return cuttingDimensions(row?.cutting_requirement_dimensions || member.dimensions) },
    qty(value) { return Number(value || 0).toLocaleString('zh-CN', { maximumFractionDigits: 8, useGrouping: false }) },
    sum(group, field) { return this.qty(group.sources.reduce((sum, row) => sum + (Number(row[field]) || 0), 0)) },
    location(row) { return (row && row.location && (row.location.location_code || row.location.location_name)) || '—' },
    receiptInvalid(row) { return ![row.receiptAccepted, row.receiptRejected].every(value => /^\d+(\.\d{1,8})?$/.test(String(value))) || Number(row.receiptAccepted) + Number(row.receiptRejected) > Number(row.pending) + 0.00000001 },
    limit(row) { return Number(this.mode === 'plan' ? row.picking_available_qty : this.mode === 'pick' ? row.planned : row.available) },
    invalid(row) { return this.mode === 'plan' ? !validCuttingSource(row) : !/^\d+(\.\d{1,8})?$/.test(String(row.quantity)) || Number(row.quantity) < 0 || Number(row.quantity) > this.limit(row) || (!!row.cuttingAllocation && !Number.isInteger(Number(row.quantity))) }
  }
}
</script>
